use super::kit::*;fn read<T:serde::de::DeserializeOwned>(a:&Value,k:&str)->Result<T,String>{serde_json::from_value(a.get(k).ok_or_else(||format!("{k} required"))?.clone()).map_err(|e|e.to_string())}
pub fn commands()->Vec<Command>{vec![
Command{name:"transform_vertex_stream",description:"Bake a raw affine transform into an editable vertex stream, fixing normals, tangents and winding. Bake raw affine transform into editable stream; inverse-transpose normals, orthogonalized tangents, reflection winding/handedness fix, singular transform rejection. No preset or project mutation.",mutates:false,schema:obj(vec![("stream",json!({"type":"object"})),("matrix",json!({"type":"array"}))],&["stream","matrix"]),run:|_,a|Ok(json!(crate::threed::node_ingest::transform(&read(a,"stream")?,read(a,"matrix")?)?))},
Command{name:"instantiate_gltf_scene",description:"Crate-backed glTF node TRS/matrix composition and explicit scene-index selection. Returns transformed per-node streams and inspectable world matrices. Materials/normal maps not applied; MikkTSpace follows normal maps. Caller supplies buffer bytes, no URI fetch.",mutates:false,schema:obj(vec![("bytes",json!({"type":"array"})),("buffers",json!({"type":"array"})),("derive_tangents",json!({"type":"boolean"})),("scene_index",json!({"type":"integer"}))],&["bytes","buffers","derive_tangents","scene_index"]),run:|_,a|{
#[cfg(feature="mesh-import")]{Ok(json!(crate::threed::node_ingest::instantiate(&read::<Vec<u8>>(a,"bytes")?,&read::<Vec<Vec<u8>>>(a,"buffers")?,read(a,"derive_tangents")?,read(a,"scene_index")?)?))}
#[cfg(not(feature="mesh-import"))]{let _=a;Err("mesh-import feature not compiled".into())}
}}]}
